<?php

declare(strict_types=1);

namespace App\Features\Blog\App\Services;

use App\Features\Blog\Domain\RepositoryInterfaces\ArticleTagRepositoryInterface;
use App\Features\Shared\Domain\ValueObjects\Slug;

/**
 * The article-tag slug resolution (content-management.md:424-464, ADR-0006 —
 * the same rules as the article/project slugs): the slug is
 * auto-generated from the EN name and editable in the form; the
 * server distinguishes the auto-generated value from a manual
 * override and re-resolves it with a numeric collision suffix when
 * the base slug is taken. The suffix query covers ALL tags (tags are
 * hard-deleted — no trashed rows). The persistence lookup is the
 * repository's `takenSlugs()`.
 */
final class TagSlugService
{
    public function __construct(
        private readonly ArticleTagRepositoryInterface $repository,
    ) {
    }

    public function resolve(
        string $submittedSlug,
        ?string $storedSlug,
        string $enName,
        ?int $ignoreId,
    ): Slug {
        $generated = Slug::generate($enName);
        $isAutoGenerated = $submittedSlug === $generated || $submittedSlug === $storedSlug;

        if (! $isAutoGenerated) {
            return new Slug($submittedSlug);
        }

        $base = $generated === '' ? 'tag' : $generated;

        $taken = $this->repository->takenSlugs($base, $ignoreId);

        if (! in_array($base, $taken, true)) {
            return new Slug($base);
        }

        $maxSuffix = 0;
        foreach ($taken as $slug) {
            if (preg_match('/^'.preg_quote($base, '/').'-(\d+)$/', $slug, $matches) === 1) {
                $maxSuffix = max($maxSuffix, (int) $matches[1]);
            }
        }

        return new Slug($base.'-'.($maxSuffix + 1));
    }
}
